def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        try:
            id_, day, flag = (field.strip() for field in line.split(","))
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"Invalid session at line {line_number}: {exc}") from exc
        if flag not in flags:
            raise ValueError(f"Invalid converted value at line {line_number}: {flag!r}")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Keep the last session per id, sorted by day and id. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if e["converted"] is True and start_day <= e["day"] <= end_day:
            counts[e["day"] - start_day] += 1
    return counts
