{"file_path":"tests/test_spec.py","content":""""Regression tests for the behavior specified in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [{"converted": True}, {"converted": None}, {"converted": False}]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    result = pooled_conversion_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts,days,expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    lines = ["", "  \t\n", "  # comment,not,a,record", " a , 2 , 1 \n",
             "b, -1 , 0", " c , 3 ,   ", "# trailing comment"]
    assert parse_session_log(iter(lines)) == [
        session("a", 2, True), session("b", -1, False), session("c", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,2", "a,2,1,extra", "a,no,1", "a,1.5,0"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    lines = ["", " # comment", "ok,1,0", " \t ", bad_line]
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(lines)


def test_dedupe_sessions_last_duplicate_id_wins_then_sorts():
    # The later record wins even when its day is earlier.
    events = [session("a", 9, True), session("z", 2, True),
              session("b", 2, True), session("a", 1, False), session("b", 2, None)]
    assert dedupe_sessions(events) == [events[3], events[4], events[1]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_dense_range():
    events = [session("before", 0, True), session("after", 5, True),
              session("last", 4, True), session("first", 1, True),
              session("another", 1, True), session("false", 2, False),
              session("unknown", 3, None)]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days,recent", [(0, 0), (1, 0), (2, 1), (3, 1), (9, 2)])
def test_campaign_summary_pooled_rounded_and_calendar_window(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 4, True), session("c", 5, False)],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "zero": [{"converted": None}],
        "a": [{"converted": True}],
        "middle": [{"converted": True}, {"converted": False}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "middle", "zero"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({}, 3) == []
    assert top_converting_groups({"empty": []}, 3) == []


def test_conversion_rate_by_group_sorted_with_none_for_empty():
    groups = {"z": [], "b": [{"converted": None}],
              "a": [{"converted": True}, {"converted": False}]}
    result = conversion_rate_by_group(groups)
    assert list(result.items()) == [("a", 0.5), ("b", 0.0), ("z", None)]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts,expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 1, 1], 2),
     ([1, 2, -1, 3], 2), ([1, 2, 3, 0, 1], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
